double fa = f(a);
double fb = f(b);
if (a == b) return 0.0;
double m = 0.5 * (a + b);
double fm = f(m);
double S = (b - a) / 6.0 * (fa + 4.0 * fm + fb);

auto simpson_rec = [&](auto&& self, double left, double right, double eps,
                      double whole, double fl, double fm, double fr) -> double {
    double mid = 0.5 * (left + right);
    double lmid = 0.5 * (left + mid);
    double rmid = 0.5 * (mid + right);
    double flmid = f(lmid);
    double frm = f(rmid);
    double Sleft  = (mid - left) / 6.0 * (fl + 4.0 * flmid + fm);
    double Sright = (right - mid) / 6.0 * (fm + 4.0 * frm + fr);
    double S2 = Sleft + Sright;
    if (std::fabs(S2 - whole) <= 15.0 * eps) {
        return S2 + (S2 - whole) / 15.0;
    }
    return self(self, left,  mid, eps / 2.0, Sleft,  fl, flmid, fm) +
           self(self, mid,   right, eps / 2.0, Sright, fm, frm,   fr);
};

return simpson_rec(simpson_rec, a, b, precision, S, fa, fm, fb);

